#include <iostream>
#include <map>
#include <print>
#include <string>
#include <vector>

struct Node {
    std::vector<std::string> owned;
    bool alive = true;
};

std::map<std::string, Node> nodes;

void destroy(const std::string &name) {
    Node &node = nodes.at(name);
    node.alive = false;
    std::println("-{}", name);
    for (auto it = node.owned.rbegin(); it != node.owned.rend(); ++it) {
        if (nodes.at(*it).alive) {
            destroy(*it);
        }
    }
}

int main() {
    std::vector<std::string> top;
    std::string command;
    while (std::cin >> command) {
        if (command == "new") {
            std::string x;
            std::cin >> x;
            nodes[x] = Node{};
            top.push_back(x);
            std::println("+{}", x);
        } else if (command == "own") {
            std::string a, x;
            std::cin >> a >> x;
            nodes[x] = Node{};
            nodes.at(a).owned.push_back(x);
            std::println("+{}", x);
        } else if (command == "use") {
            std::string a, b;
            std::cin >> a >> b;
            if (nodes.at(b).alive) {
                std::println("{} → {}", a, b);
            } else {
                std::println("{} → {}: висячая ссылка", a, b);
            }
        } else {
            std::string x;
            std::cin >> x;
            destroy(x);
        }
    }
    for (auto it = top.rbegin(); it != top.rend(); ++it) {
        if (nodes.at(*it).alive) {
            destroy(*it);
        }
    }
    return 0;
}

